import React, { useState, useEffect } from "react";
import { fetchUserHistory } from "../api";

export default function AnalysisHistoryModal({ isOpen, onClose }) {
  const [history, setHistory] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    if (isOpen) {
      setLoading(true);
      setError("");
      fetchUserHistory(50, 0)
        .then((data) => setHistory(data.history || []))
        .catch((err) => setError("Failed to load history: " + (err.message || "Network error")))
        .finally(() => setLoading(false));
    }
  }, [isOpen]);

  if (!isOpen) return null;

  return (
    <div style={overlayStyle}>
      <div style={modalStyle}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "1rem" }}>
          <div>
            <h2 style={{ margin: 0, fontSize: "1.25rem", color: "#1e293b" }}>Analysis & Scan History</h2>
            <p style={{ margin: "0.25rem 0 0 0", fontSize: "0.85rem", color: "#64748b" }}>
              Review your previous packaging OCR and barcode verifications.
            </p>
          </div>
          <button onClick={onClose} style={closeButtonStyle}>×</button>
        </div>

        {loading && <p style={{ color: "#64748b", fontSize: "0.9rem" }}>Loading history records...</p>}
        {error && <p style={{ color: "#b91c1c", fontSize: "0.85rem" }}>{error}</p>}

        {!loading && history.length === 0 && !error && (
          <div style={{ textAlign: "center", padding: "2rem", color: "#94a3b8" }}>
            No scan history found. Scans performed while logged in will appear here.
          </div>
        )}

        {!loading && history.length > 0 && (
          <div style={{ overflowX: "auto" }}>
            <table style={{ width: "100%", borderCollapse: "collapse", fontSize: "0.82rem" }}>
              <thead>
                <tr style={{ backgroundColor: "#f8fafc", borderBottom: "2px solid #e2e8f0", textAlign: "left" }}>
                  <th style={thStyle}>Date & Time</th>
                  <th style={thStyle}>Product / Barcode</th>
                  <th style={thStyle}>Safety Score</th>
                  <th style={thStyle}>Personal Score</th>
                  <th style={thStyle}>Allergens</th>
                  <th style={thStyle}>Additives</th>
                </tr>
              </thead>
              <tbody>
                {history.map((rec) => {
                  const hasAllergens = rec.allergen_alerts && rec.allergen_alerts.length > 0;
                  return (
                    <tr key={rec.id} style={{ borderBottom: "1px solid #f1f5f9" }}>
                      <td style={tdStyle}>{rec.scanned_at ? rec.scanned_at.slice(0, 16) : "N/A"}</td>
                      <td style={tdStyle}>
                        <div style={{ fontWeight: 600, color: "#1e293b" }}>{rec.product_name}</div>
                        <div style={{ fontSize: "0.75rem", color: "#64748b" }}>{rec.ean !== "N/A" ? rec.ean : "OCR Scan"}</div>
                      </td>
                      <td style={tdStyle}>
                        <span style={{
                          fontWeight: 700,
                          padding: "0.15rem 0.4rem",
                          borderRadius: "4px",
                          backgroundColor: rec.final_score >= 80 ? "#dcfce7" : rec.final_score >= 60 ? "#fef3c7" : "#fee2e2",
                          color: rec.final_score >= 80 ? "#166534" : rec.final_score >= 60 ? "#854d0e" : "#991b1b"
                        }}>
                          {rec.final_score} ({rec.grade})
                        </span>
                      </td>
                      <td style={tdStyle}>
                        <span style={{
                          fontWeight: 700,
                          padding: "0.15rem 0.4rem",
                          borderRadius: "4px",
                          backgroundColor: rec.personal_score >= 90 ? "#dcfce7" : rec.personal_score >= 70 ? "#fef3c7" : "#fee2e2",
                          color: rec.personal_score >= 90 ? "#166534" : rec.personal_score >= 70 ? "#854d0e" : "#991b1b"
                        }}>
                          {rec.personal_score}/100
                        </span>
                        <div style={{ fontSize: "0.72rem", color: "#64748b", marginTop: "0.15rem" }}>{rec.personal_verdict}</div>
                      </td>
                      <td style={tdStyle}>
                        {hasAllergens ? (
                          <span style={{ color: "#dc2626", fontWeight: 700 }}>
                            ⚠️ {rec.allergen_alerts.length} Detected
                          </span>
                        ) : (
                          <span style={{ color: "#16a34a" }}>None</span>
                        )}
                      </td>
                      <td style={tdStyle}>
                        <span style={{ color: "#475569" }}>
                          {rec.additives_count > 0 ? `${rec.additives_count} found` : "None"}
                        </span>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}

        <div style={{ display: "flex", justifyContent: "flex-end", marginTop: "1.25rem" }}>
          <button onClick={onClose} style={closeActionStyle}>Close</button>
        </div>
      </div>
    </div>
  );
}

const overlayStyle = {
  position: "fixed",
  top: 0,
  left: 0,
  right: 0,
  bottom: 0,
  backgroundColor: "rgba(15, 23, 42, 0.6)",
  display: "flex",
  justifyContent: "center",
  alignItems: "center",
  zIndex: 1000,
  padding: "1rem"
};

const modalStyle = {
  backgroundColor: "#ffffff",
  borderRadius: "12px",
  padding: "1.75rem",
  width: "100%",
  maxWidth: "750px",
  maxHeight: "85vh",
  overflowY: "auto",
  boxShadow: "0 20px 25px -5px rgba(0, 0, 0, 0.1)"
};

const closeButtonStyle = {
  background: "none",
  border: "none",
  fontSize: "1.5rem",
  color: "#64748b",
  cursor: "pointer"
};

const thStyle = {
  padding: "0.6rem 0.75rem",
  color: "#475569",
  fontWeight: 600,
  fontSize: "0.8rem"
};

const tdStyle = {
  padding: "0.6rem 0.75rem",
  verticalAlign: "middle"
};

const closeActionStyle = {
  padding: "0.5rem 1rem",
  backgroundColor: "#f1f5f9",
  color: "#475569",
  border: "1px solid #cbd5e1",
  borderRadius: "6px",
  fontWeight: 600,
  cursor: "pointer"
};
